def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    points = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                points[grid[r][c]] = (r, c)

    def put(r, c, v):
        if 0 <= r < h and 0 <= c < w:
            out[r][c] = v

    # Each symbol draws its characteristic trail.
    for v, (r, c) in points.items():
        if v == 1:
            put(r, c + 1, 5)
            put(r, c + 2, 5)
            put(r - 1, c + 2, 1)
        elif v == 2:
            put(r, c - 4, 2)
            for x in range(c - 3, c):
                put(r, x, 5)
        elif v == 3:
            for y in range(r + 1, r + 3):
                put(y, c, 5)
            put(r + 3, c, 3)
        elif v == 6:
            for y in range(r - 1, r - 6, -1):
                put(y, c, 5)
            put(r - 6, c, 6)

    # A vertical 3/6 trail crossing the horizontal 2 trail makes a
    # diagonal trail of 4s.
    if 2 in points:
        r2, c2 = points[2]
        for v in (3, 6):
            if v in points:
                rv, cv = points[v]
                vertical_rows = range(rv + 1, rv + 4) if v == 3 else range(rv - 6, rv)
                if cv == c2 - 2 and r2 in vertical_rows:
                    put(r2, cv, 4)
                    d = 1
                    while r2 + d < h and cv - d >= 0:
                        put(r2 + d, cv - d, 4)
                        d += 1

    # Restore original markers.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                out[r][c] = grid[r][c]
    return out
